    id: "ge-tbilisi-cities-v2",
    type: "state-capital",
    parent: "GE-TB",
    coords: [44.7833, 41.7166],
    descriptionAdvanced: {
      de: "Tiflis, die georgische Hauptstadt, erstreckt sich malerisch an den Ufern des Flusses Kura (Mtkvari) und ist das pulsierende Herz des Kaukasus. Die Stadt wurde im 5. Jahrhundert von König Wachtang I. Gorgassali gegründet, der laut Legende von den heißen Schwefelquellen so beeindruckt war, dass er die Hauptstadt hierher verlegte. Der Name der Stadt leitet sich vom georgischen Wort für „warm“ ab. Heute präsentiert sich Tiflis als eine faszinierende Mischung aus Geschichte und Moderne. In der Altstadt (Abanotubani) dominieren die charakteristischen Schwefelbäder mit ihren gemauerten Kuppeln und die engen Gassen mit bunten Holzbalkonen. Hoch über der Stadt thront die Festung Narikala, die einen Panoramablick über das gesamte Becken bietet. Tiflis hat eine bewegte Geschichte hinter sich, die von persischen, osmanischen und russischen Einflüssen geprägt wurde, was sich in der Architektur widerspiegelt – von byzantinischen Kirchen über neoklassizistische russische Prachtbauten bis hin zu gewagten modernen Glas- und Stahlkonstruktionen wie der Friedensbrücke. Wirtschaftlich ist Tiflis das Zentrum für Handel, Bankwesen und Leichtindustrie in Georgien. Die Stadt hat sich zu einem bedeutenden regionalen Logistikknotenpunkt an der Schnittstelle zwischen Europa und Asien entwickelt. Kulturell bietet Tiflis eine reiche Opernszene, zahlreiche Theater und eine boomende Kunstgalerie-Landschaft. Die demografische Struktur ist vielfältig, wobei Georgier die Mehrheit bilden, aber auch bedeutende armenische, aserbaidschanische und russische Minderheiten das Stadtbild bereichern. Die gastronomische Szene ist weltberühmt für ihre Khinkali und Khachapuri, begleitet von den hervorragenden Weinen der Region Kakheti. Bildungstechnisch beheimatet die Stadt die Staatliche Universität Tiflis, die älteste im Kaukasus, sowie zahlreiche spezialisierte Forschungsinstitute.",
      hu: "Tbiliszi nem csupán Grúzia fővárosa, hanem a Kaukázus térségének történelmi és kulturális epicentruma is, ahol az ősi selyemút hagyományai találkoznak a 21. századi modernizmussal. A város fekvése különleges: a Mtkvari (Kura) folyó völgyében, meredek dombok és hegyek közé ékelődve terül el, ami egyedi klímát és látképet biztosít. A magyar utazók számára Tbiliszi gyakran emlékeztet a történelmi sorsfordulókra, hiszen a város számtalanszor épült újjá a pusztító inváziók után. A 4. századi Narikala-erőd falai között járva megelevenedik a múlt, míg a Rusztaveli sugárút neoklasszicista palotái a 19. századi orosz birodalmi korszakot idézik. A város gazdasági motorja az utóbbi évtizedekben jelentős átalakuláson ment keresztül, a korábbi nehézipari fókuszt felváltotta a turizmus, a pénzügyi szolgáltatások és a technológiai szektor. Tbiliszi híres vendégszeretetéről és gasztronómiájáról; a helyi piacok és a modern éttermek egyaránt a grúz konyha sokszínűségét hirdetik. A város vallási élete is meghatározó, a Szentháromság-székesegyház (Sameba) az ország egyik legnagyobb és legfontosabb ortodox temploma, amelynek aranykupolája messziről látható. A kulturális életet a Grúz Nemzeti Múzeum kincsei, az operaház díszes előadásai és a Függetlenség tere körüli pezsgő éjszakai élet határozza meg. Az oktatás terén a város kiemelkedik, hiszen itt találhatók az ország legfontosabb egyetemei, amelyek a kaukázusi régió tudományos központjaivá váltak. A környező hegyekben található parkok és a teknősbéka-tó népszerű kikapcsolódási helyszínek, ahonnan fentről szemlélhető a város állandó mozgása és fejlődése.",
      ro: "Tbilisi, capitala Georgiei, reprezintă o fuziune spectaculoasă între tradiția caucaziană și influențele europene, fiind situată strategic pe malurile râului Mtkvari. Istoria orașului începe în secolul al V-lea, când regele Vakhtang Gorgasali a descoperit izvoarele termale sulfuroase care dau și numele localității. Arhitectura orașului este o cronică vizuală a secolelor trecute, unde bisericile ortodoxe medievale cu turlele lor conice specifice stau alături de edificii moderne din sticlă și oțel. Centrul vechi, cu străzile sale pavate și balcoanele din lemn sculptat, este protejat ca patrimoniu istoric, fiind locul unde se află faimoasele băi de sulf Abanotubani. Economia orașului Tbilisi este cea mai dinamică din Georgia, concentrând majoritatea investițiilor străine în sectoare precum construcțiile, energia și comerțul. Portul fluvial și legăturile feroviare fac din oraș un nod logistic vital pentru transportul de mărfuri între Marea Cască și Marea Neagră. Din punct de vedere demografic, Tbilisi este un mozaic cultural, unde comunități de evrei, musulmani și creștini au conviețuit pașnic de secole, fapt demonstrat de proximitatea sinagogilor, moscheilor și bisericilor din cartierele vechi. Viața culturală este vibrantă, marcată de festivaluri de jazz, expoziții de artă contemporană și spectacole de dans tradițional georgian care uimesc prin dinamism. Bulevardul Rustaveli, artera principală, găzduiește Parlamentul, Opera și Muzeul Național, fiind locul unde s-au desfășurat cele mai importante evenimente politice din istoria modernă a țării. Orașul este de asemenea un centru universitar major, atrăgând mii de studenți străini, în special la medicină și tehnologie. Tbilisi rămâne o destinație turistică de top, oferind vizitatorilor nu doar istorie, ci și o experiență culinară unică bazată pe ingrediente naturale și rețete transmise din generație în generație.",
      en: "Tbilisi, the capital and largest city of Georgia, stands as a testament to resilience and cultural richness at the crossroads of Europe and Asia. Nestled in the valley of the Kura (Mtkvari) River, the city's geography is defined by the Trialeti Range to the west and the Kartli Range to the north and east. Founded in the 5th century by King Vakhtang Gorgasali, Tbilisi has served as the capital of various Georgian kingdoms and republics for over 1,500 years. Its location on the historic Silk Road made it a coveted prize for various empires, including Persians, Byzantines, Arabs, Mongols, and Russians, each leaving an indelible mark on its urban fabric. The Old Town is a maze of narrow streets, traditional brick houses with wooden balconies, and ancient churches like the Anchiskhati Basilica. In contrast, the post-Soviet era has introduced bold architectural experiments, such as the Public Service Hall and the Rike Park concert hall. Economically, Tbilisi is the hub of the Georgian economy, contributing significantly to the national GDP through services, tourism, and manufacturing. The city's financial district is growing rapidly, reflecting Georgia's liberal economic reforms. Demographically, Tbilisi is home to approximately 1.2 million people, representing a melting pot of ethnic Georgians, Armenians, Azerbaijanis, and Russians. The cultural scene is incredibly diverse, ranging from the classical performances at the Tbilisi Opera and Ballet Theater to the underground techno scene centered around the world-famous Bassiani club. Education is a cornerstone of the city, with Tbilisi State University and the Georgian Technical University being the leading institutions. The city is also known for its stunning surroundings, including the Tbilisi Sea reservoir and the Holy Mountain (Mtatsminda), which offers breathtaking views and an amusement park accessible by funicular.",
    },
