      de: "Tiflis ist die Hauptstadt und größte Stadt Georgiens, malerisch am Ufer der Kura gelegen. Die Architektur ist eine Mischung aus historischen Kirchen, Jugendstilgebäuden und moderner Architektur.",
      hu: "Tbiliszi Grúzia fővárosa és legnagyobb városa, amely festői módon a Kura folyó partján fekszik. Építészetében a történelmi templomok és a modern épületek keverednek.",
      ro: "Tbilisi este capitala și cel mai mare oraș al Georgiei, situat pitoresc pe malurile râului Kura. Arhitectura sa este un amestec de biserici istorice și clădiri moderne.",
      en: "Tbilisi is the capital and largest city of Georgia, picturesquely situated on the banks of the Kura River. Its architecture is a mix of historical churches and modern buildings.",
      es: "Tiflis es la capital y la ciudad más grande de Georgia, pintorescamente situada a orillas del Kura. Su arquitectura es una mezcla de iglesias históricas, edificios Art Nouveau y arquitectura moderna.",
      pt: "Tiblíssi é a capital e a maior cidade da Geórgia, pitorescamente situada nas margens do Kura. A sua arquitetura é uma mistura de igrejas históricas, edifícios Art Nouveau e arquitetura moderna.",
