    type: "city",
    parent: "GE-IM",
    coords: [42.7000, 42.2500],
    descriptionAdvanced: {
      de: "Kutaissi ist die drittgrößte Stadt Georgiens und das historische Zentrum der westgeorgischen Region Imeretien. Sie liegt malerisch am Fluss Rioni am Fuß der Berge des Großen Kaukasus und blickt auf eine über 3500-jährige Besiedlungsgeschichte zurück, was sie zu einer der ältesten kontinuierlich bewohnten Städte Europas macht. Schon in der Antike war Kutaissi unter dem Namen Aia die mythische Hauptstadt des Königreichs Kolchis, in das Iason und die Argonauten der griechischen Sage nach dem Goldenen Vlies aufbrachen. Vom 8. bis zum 12. Jahrhundert war die Stadt mehrfach Residenzstadt georgischer Könige, und David IV. der Erbauer ließ hier die heute zum UNESCO-Welterbe gehörende Bagrati-Kathedrale errichten. Wichtige Sehenswürdigkeiten sind außerdem das Kloster Gelati mit seinen mittelalterlichen Mosaiken und Fresken, das Kolchidische Museum und die unterirdischen Höhlen von Sataplia und Prometheus in der Umgebung. Von 2012 bis 2018 tagte hier zudem das georgische Parlament; heute ist Kutaissi mit dem internationalen Flughafen Kopitnari ein Drehkreuz für Billigflüge in den Süd-Kaukasus.",
      hu: "Kutaiszi Grúzia harmadik legnagyobb városa, Imereti történelmi központja Nyugat-Grúziában. Festői módon a Rioni folyó partján fekszik, a Nagy-Kaukázus előhegyei alatt, és több mint 3500 éves megtelepedési múltja Európa egyik legrégebben folyamatosan lakott települései közé sorolja. Az ókorban Aia néven az Argonauták legendájában szereplő mitikus Kolkhisz királyság fővárosa volt, ahová a görög monda szerint Iaszón és társai az aranygyapjúért indultak. A 8. és 12. század között Kutaiszi többször grúz királyi székhelyül szolgált, IV. (Építő) Dávid uralkodása alatt épült a ma UNESCO-világörökség részét képező Bagrati-székesegyház. További jelentős látnivaló a Gelati-kolostor középkori mozaikjaival és freskóival, a Kolkhiszi Múzeum, valamint a város közelében lévő Szatapliai és Prométheusz cseppkőbarlangok. 2012 és 2018 között itt ülésezett a grúz parlament is; ma Kutaiszi a Kopitnari nemzetközi repülőtérnek köszönhetően a Dél-Kaukázus egyik fontos fapados légi csomópontja.",
      ro: "Kutaisi este al treilea oraș ca mărime al Georgiei și centrul istoric al regiunii Imereti, în vestul țării. Așezat pitoresc pe râul Rioni, la poalele munților Caucazului Mare, are o continuitate de locuire de peste 3.500 de ani, fiind printre cele mai vechi orașe locuite neîntrerupt din Europa. În Antichitate, sub numele Aia, era capitala mitică a regatului Colchida, locul unde, potrivit legendei grecești, Iason și argonauții au pornit în căutarea Lânii de Aur. Între secolele al VIII-lea și al XII-lea, Kutaisi a servit de mai multe ori drept reședință a regilor Georgiei, iar David al IV-lea Constructorul a ridicat aici Catedrala Bagrati, astăzi parte a patrimoniului mondial UNESCO. Alte obiective importante sunt Mănăstirea Gelati, cu mozaicuri și fresce medievale, Muzeul Colchidei și peșterile Sataplia și Prometeu din împrejurimi. Între 2012 și 2018, orașul a găzduit și sediul Parlamentului Georgiei, iar prin aeroportul internațional Kopitnari Kutaisi a devenit un hub regional pentru zboruri low-cost în Caucazul de Sud.",
      en: "Kutaisi is Georgia's third-largest city and the historic capital of the western region of Imereti. Set picturesquely on the banks of the Rioni River at the foot of the Greater Caucasus, it has been inhabited for more than 3,500 years, ranking among the oldest continuously occupied cities in Europe. In antiquity, under the name Aia, it was the mythical capital of the kingdom of Colchis, the destination of Jason and the Argonauts in their Greek legendary quest for the Golden Fleece. Between the 8th and 12th centuries the city served repeatedly as the seat of Georgian kings; under David IV the Builder the Bagrati Cathedral was erected here, today a UNESCO World Heritage Site. Other major attractions include the medieval Gelati Monastery, with its renowned mosaics and frescoes, the Museum of Colchis, and the Sataplia and Prometheus cave systems on the city's outskirts. From 2012 to 2018 Kutaisi also hosted Georgia's national parliament, and via Kopitnari International Airport it has become a regional hub for low-cost flights into the South Caucasus.",
image: "/poi-images/ge-kutaisi-cities-v2.webp",
      es: "Kutaisi es el corazón histórico de Imericia, situada a orillas del río Rioni, al pie del Cáucaso. Con 3.500 años de historia, es una de las urbes más antiguas de Europa. En la antigüedad fue Aia, capital mítica del Reino de Cólquida, destino de Jasón y los Argonautas en busca del Vellocino de Oro. Fue residencia real del siglo VIII al XII, y David IV mandó construir allí la Catedral de Bagrati (Patrimonio UNESCO). Otros tesoros incluyen el Monasterio de Gelati con sus mosaicos medievales, el Museo Colchídico y las cuevas de Sataplia y Prometeo. De 2012 a 2018 albergó el Parlamento de Georgia; hoy es un nodo aéreo clave con el aeropuerto internacional de Kopitnari.",
      pt: "Kutaisi é a terceira maior cidade da Geórgia e o centro histórico da região de Imereti. Situada nas margens do rio Rioni, possui mais de 3.500 anos de história, sendo uma das cidades mais antigas da Europa. Na Antiguidade, sob o nome Aia, foi a capital do reino de Colchis, onde os Argonautas procuraram o Velocino de Ouro. Entre os séculos VIII e XII, foi residência de reis georgianos, e David IV construiu aqui a Catedral Bagrati (UNESCO). Outros pontos de interesse são o Mosteiro de Gelati, o Museu de Colchis e as grutas de Sataplia e Prometeu. Sede do Parlamento georgiano entre 2012 e 2018, é hoje um importante centro de voos low-cost com o aeroporto de Kopitnari.",
      fr: "Troisième ville du pays, Koutaïssi est le centre historique de l'Iméréthie. Pittoresquement installée sur le fleuve Rioni au pied du Grand Caucase, elle affiche 3 500 ans d'histoire, ce qui en fait l'une des plus anciennes cités d'Europe. Dans l'Antiquité, sous le nom d'Aïa, elle était la capitale mythique du royaume de Colchide, où Jason et les Argonautes cherchèrent la Toison d'or. Résidence royale du VIIIe au XIIe siècle, elle vit l'édification par David le Bâtisseur de la cathédrale de Bagrati (UNESCO). À voir également : le monastère de Ghélati, le musée de la Colchide et les grottes de Prométhée. Siège du Parlement géorgien de 2012 à 2018, elle est aujourd'hui un carrefour aérien grâce à son aéroport international Kopitnari.",
},
