      de: "Rustawi ist eine bedeutende Industriestadt im Südosten Georgiens am Fluss Kura. Die Stadt wurde in der sowjetischen Ära stark ausgebaut und geprägt.",
      hu: "Rusztawi jelentős iparváros Grúzia délkeleti részén, a Kura folyó mentén. A várost a szovjet korszakban erősen fejlesztették és alakították.",
      ro: "Rustavi este un important oraș industrial în sud-estul Georgiei, pe râul Kura. Orașul a fost puternic dezvoltat în perioada sovietică.",
      en: "Rustavi is a major industrial city in southeastern Georgia on the Kura River. The city was heavily developed during the Soviet era.",
