      pt: "Rustavi é uma importante cidade industrial no sudeste da Geórgia, nas margens do rio Kura. A cidade foi fortemente desenvolvida e marcada durante a era soviética.",
      fr: "Rustavi est une ville industrielle majeure du sud-est de la Géorgie, située sur les rives du fleuve Koura. Elle a été fortement développée et marquée par l'époque soviétique.",
