      hu: ["Maga Sztálin is rendszeresen látogatta Chaltubo fürdőit.", "Számos szanatóriumot ma fokozatosan újítanak fel."],
      ro: ["Stalin însuși vizita regulat băile din Tskhaltubo.", "Multe sanatorii sunt restaurate treptat astăzi."],
      en: ["Stalin himself regularly visited the baths in Tskhaltubo.", "Many sanatoriums are gradually being restored today."],
      es: ["El propio Stalin visitaba regularmente los baños de Tskhaltubo.", "Muchos sanatorios se están restaurando gradualmente en la actualidad."],
      pt: ["O próprio Stalin visitava regularmente os banhos em Tskhaltubo.", "Muitos sanatórios estão a ser restaurados gradualmente."],
      fr: ["Staline lui-même fréquentait régulièrement les bains de Tskhaltubo.", "De nombreux sanatoriums sont aujourd'hui progressivement restaurés."],
