      hu: ["A termálforrások hőmérséklete állandó 33 °C.", "Kutaiszitól mindössze 12 kilométerre északnyugatra fekszik.", "22 monumentális szovjet szanatórium épült a városban.", "Sztálin saját különteremmel rendelkezett a 6-os fürdőben.", "A források vize enyhén radioaktív tulajdonságú.", "A közelben dinoszaurusz lábnyomok láthatók Satapliában."],
      ro: ["Izvoarele termale au o temperatură constantă de 33 °C.", "Situat la 12 kilometri nord-vest de orașul Kutaisi.", "Orașul include 22 de sanatorii din epoca sovietică.", "Stalin avea un cabinet privat în cadrul Băii Nr. 6.", "Apele sunt eficiente în tratarea reumatismului.", "Găzduiește peștera Prometeu, faimoasă pentru stalactite."],
      en: ["Thermal springs maintain a constant temperature of 33 °C.", "Located 12 kilometers northwest of the city of Kutaisi.", "Home to 22 monumental Soviet-era sanatoria.", "Stalin had a private pool and cabinet in Bath No. 6.", "The springs are credited with helping rheumatic complaints.", "Nearby Prometheus Cave is one of Georgia's largest."],
      es: ["Las fuentes termales mantienen una temperatura constante de 33 °C.", "Se encuentra a unos 12 kilómetros al noroeste de Kutaisi.", "Cuenta con 22 sanatorios monumentales de la era soviética.", "Stalin disponía de una piscina privada en el Baño n.º 6.", "Fue desarrollado como balneario modelo en el siglo XX.", "La famosa Cueva de Prometeo se encuentra en las cercanías."],
      pt: ["As fontes termais têm uma temperatura constante de 33 °C.", "Localiza-se a cerca de 12 quilómetros a noroeste de Kutaisi.", "Possui 22 sanatórios monumentais da era soviética.", "Stalin tinha uma piscina privada no Banho n.º 6.", "Foi desenvolvida como uma estância termal modelo no século XX.", "A famosa Gruta de Prometeu situa-se nas proximidades."],
      fr: ["Les sources thermales ont une température constante de 33 °C.", "Située à environ 12 kilomètres au nord-ouest de Koutaïssi.", "Possède 22 sanatoriums monumentaux de l'époque soviétique.", "Staline avait une piscine privée réservée dans le bain n° 6.", "Développée comme station thermale modèle au XXe siècle.", "La célèbre grotte de Prométhée se trouve à proximité."],
