    type: "city",
    parent: "GE-IM",
    coords: [43.2800, 42.2900],
    descriptionAdvanced: {
      de: "Tschiatura ist mit rund 12.000 Einwohnern eine außergewöhnliche Bergbaustadt im westgeorgischen Imeretien, eingezwängt in eine über 400 Meter tiefe Schlucht des Flusses Kwirila. Bekannt geworden ist sie vor allem durch ihre weltweit einzigartige Manganerzlagerstätte, die seit 1879 industriell ausgebeutet wird; in Spitzenjahren der Sowjetzeit kamen aus Tschiatura über 60 % des sowjetischen Mangans und ein bedeutender Anteil der Weltproduktion. Da die Erzflöze hoch oben auf den Schluchträndern liegen, errichtete die Bergbaubehörde ab 1954 ein einmaliges Netz von Personenseilbahnen, das mehr als 17 Linien umfasste und die Stadtteile auf den Hochebenen mit den Schächten und dem Tal verband. Viele dieser Seilbahnen, einschließlich der ältesten erhaltenen Personenseilbahn der Welt, wurden ab 2018 saniert und erstrahlen heute mit modernen, gläsernen Kabinen. Sehenswert sind außerdem das stalinistisch geprägte Stadtzentrum, das Bergbau-Museum, die Felsenkirche Katsche-Säule, die auf einem 40 Meter hohen Felsmonolithen über der Schlucht thront, sowie das mittelalterliche Höhlenkloster Mghwimewi.",
      hu: "Csiatura mintegy 12 000 lakossal különleges bányászváros Imereti régióban, Nyugat-Grúziában, a Kvirila folyó több mint 400 méter mély szurdokába szorítva. Igazi hírnevét a világon is egyedülálló mangánérc-lelőhelyének köszönheti, amelyet 1879 óta iparszerűen művelnek; a szovjet csúcsidőszakban a szovjet mangántermelés több mint 60 %-a és a világtermelés jelentős hányada Csiaturából érkezett. Mivel az ércerek a szurdok peremén húzódó fennsíkokon találhatók, a bányászati hatóság 1954-től egy egyedülálló, több mint 17 vonalból álló személyszállító kötélpálya-hálózatot épített ki, amely a fennsíkon lévő városrészeket kötötte össze az aknákkal és a völggyel. A világ legrégebbi máig fennmaradt személyszállító kötélpályáját is magában foglaló rendszer egy részét 2018-tól felújították, és ma korszerű, üveges kabinokkal közlekedik. Érdemes megnézni a sztálinista városközpontot, a bányászati múzeumot, a szurdok fölé 40 méter magasan emelkedő sziklamonolitra épült Kacshi-oszlop sziklatemplomát, valamint a középkori Mgvimevi sziklakolostort.",
      ro: "Chiatura, cu aproximativ 12.000 de locuitori, este un oraș minier cu totul aparte din regiunea Imereti, în vestul Georgiei, înghesuit într-un defileu adânc de peste 400 de metri al râului Kvirila. Faima sa vine de la zăcământul unic de minereu de mangan, exploatat industrial din 1879; în perioada de vârf a epocii sovietice, peste 60 % din producția sovietică de mangan și o parte importantă din producția mondială provenea de la Chiatura. Întrucât straturile de minereu se află pe podișurile de la marginea defileului, autoritățile miniere au construit din 1954 o rețea unică de telecabine de pasageri, cu peste 17 linii, care lega cartierele de pe înălțimi de minele și de centrul din vale. O parte din acest sistem, inclusiv cea mai veche telecabină de călători din lume aflată încă în funcțiune, a fost modernizată din 2018 cu cabine moderne, cu pereți de sticlă. Pot fi vizitate centrul orașului în stil stalinist, muzeul mineritului, biserica rupestră Katskhi, ridicată pe un monolit stâncos de 40 de metri deasupra defileului, și mănăstirea medievală Mghvimevi.",
      en: "Chiatura, with around 12,000 inhabitants, is an extraordinary mining town in the Imereti region of western Georgia, squeezed into a more than 400-metre-deep gorge of the Kvirila River. Its fame rests on a globally unique manganese deposit that has been industrially exploited since 1879; at the height of the Soviet period more than 60 % of Soviet manganese and a significant share of world output came from Chiatura. Because the ore seams lie on plateaus high above the gorge, from 1954 the mining authority built a remarkable network of passenger ropeways, with more than 17 lines connecting cliff-top neighbourhoods with the mines and the valley below. Parts of this system, including one of the oldest passenger ropeways still in operation worldwide, have been refurbished since 2018 with modern glass-walled cabins. Other highlights include the Stalinist town centre, the Mining Museum, the Katskhi Pillar with its rock-hewn church atop a 40-metre limestone monolith and the medieval Mghvimevi cave monastery.",
image: "/poi-images/ge-chiatura-cities-v2.webp",
      es: "Chiatura, con 12.000 habitantes en la región de Imereti, es una ciudad minera extraordinaria encajada en un cañón de 400 metros de profundidad. Es mundialmente conocida por sus yacimientos de manganeso, explotados desde 1879, que llegaron a suministrar el 60% de la producción soviética. Debido a que las minas están en lo alto de los acantilados, en 1954 se creó una red única de teleféricos para transportar a mineros y ciudadanos, incluyendo el teleférico de pasajeros más antiguo del mundo. Desde 2018, muchas de estas líneas han sido modernizadas con cabinas de cristal. Cerca de la ciudad se encuentra el impresionante Pilar de Katskhi, un monolito de 40 metros con una iglesia en su cima, y el monasterio rupestre de Mghvimevi.",
      pt: "Chiatura, com cerca de 12.000 habitantes na região de Imereti, é uma cidade mineira extraordinária encravada num desfiladeiro com mais de 400 metros de profundidade. É famosa pelos seus depósitos de manganês, explorados desde 1879, que chegaram a representar 60% da produção soviética. Como as minas se situam no topo das falésias, foi criada a partir de 1954 uma rede única de teleféricos, com mais de 17 linhas, para ligar a cidade às minas e planaltos. Muitos destes teleféricos foram modernizados a partir de 2018. Nas proximidades encontram-se o espetacular Pilar de Katskhi, com uma igreja no topo de um monolito de 40 metros, e o mosteiro rupestre de Mghvimevi.",
      fr: "Chiatura, avec environ 12 000 habitants en Iméréthie, est une ville minière extraordinaire encaissée dans une gorge de 400 mètres de profondeur. Elle est célèbre pour ses gisements de manganèse exploités depuis 1879, ayant fourni jusqu'à 60 % de la production soviétique. Les gisements se trouvant sur les plateaux, un réseau unique de téléphériques fut créé dès 1954 pour relier la ville aux mines et aux quartiers hauts. Plusieurs de ces lignes, dont la plus vieille au monde encore en service, ont été modernisées depuis 2018 avec des cabines vitrées. À proximité se trouvent le spectaculaire pilier de Katskhi, surmonté d'une église à 40 mètres de haut, et le monastère troglodytique de Mghvimévi.",
},
