      hu: "Csiatura egy egyedülálló hegyi város, amely híres kiterjedt szovjet drótkötélpálya-hálózatáról. A város egy mély szurdokban fekszik, ahol mangánt bányásznak.",
      ro: "Chiatura este un oraș montan unic, renumit pentru rețeaua sa extinsă de telecabine sovietice. Orașul se află într-un defileu adânc unde se extrage mangan.",
