      hu: ["Mindössze néhány kilométerre fekszik az azeri határtól.", "Itt üzemel Grúzia egyik legnagyobb hőerőműve.", "A Mtkvari (Kura) folyó menti sztyeppés síkságon található.", "Fontos vasúti csomópont az Azerbajdzsán felé vezető vonalon.", "Lakossága grúz, azeri, orosz és örmény etnikumokból áll.", "A közelben ártéri erdőket védő természetvédelmi terület van."],
      ro: ["Situat la mică distanță de granița cu Azerbaidjan.", "Găzduiește cea mai mare termocentrală din Georgia.", "Amplasat pe râul Mtkvari (Kura), într-o câmpie de stepă.", "Nod important pentru tranzitul de gaze și petrol.", "Populație diversă formată din georgieni și azeri.", "Include rezervația naturală Gardabani cu păduri de luncă."],
      en: ["Located only a few kilometers from the Azerbaijan border.", "Site of one of the largest power plants in Georgia.", "Situated on the Mtkvari (Kura) River in a steppe plain.", "Key center for oil refining and gas compression.", "Population includes Georgians, Azerbaijanis, and Armenians.", "Home to a nature reserve with riparian forests."],
      es: ["Se encuentra a pocos kilómetros de la frontera con Azerbaiyán.", "Sede de la mayor central térmica de Georgia.", "Situada a orillas del río Mtkvari (Kura) en la llanura esteparia.", "Importante centro de refinación de petróleo y compresión de gas.", "Población multiétnica con georgianos y azerbaiyanos.", "Alberga la reserva natural de Gardabani."],
      pt: ["Localiza-se a poucos quilómetros da fronteira com o Azerbaijão.", "Sede da maior central termoelétrica da Geórgia.", "Situada junto ao rio Mtkvari (Kura) na planície de estepe.", "Centro importante para refinação de petróleo e compressão de gás.", "População multiétnica com georgianos e azeris.", "Abriga a reserva natural de Gardabani."],
      fr: ["Située à quelques kilomètres seulement de la frontière azerbaïdjanaise.", "Emplacement de la plus grande centrale thermique de Géorgie.", "Située au bord du fleuve Mtkvari (Koura) dans la plaine steppique.", "Centre majeur pour le raffinage du pétrole et la compression du gaz.", "Population multiethnique composée de Géorgiens et d'Azerbaïdjanais.", "Abrite la réserve naturelle de Gardabani."],
