      es: ["Fundada en 1942 como centro para la minería de carbón.", "Situada a unos 290 metros de altitud junto al río Galidzga.", "Llegó a tener unos 22.000 habitantes en la época soviética.", "Sobrevivió a un asedio de 13 meses durante la guerra de 1992-1993.", "Hoy en día viven allí menos de 5.000 personas.", "Alberga ruinas notables en el estilo del clasicismo socialista."],
      pt: ["Fundada em 1942 como centro de mineração de carvão.", "Localizada a cerca de 290 metros de altitude junto ao rio Galidzga.", "Teve cerca de 22.000 habitantes durante o período soviético.", "Sobreviveu a um cerco de 13 meses na guerra de 1992-1993.", "Hoje vivem lá menos de 5.000 pessoas.", "Possui ruínas marcantes no estilo do classicismo socialista."],
