    type: "city",
    parent: "GE-KK",
    coords: [44.5389, 41.4472],
    descriptionAdvanced: {
      de: "Bolnissi ist mit rund 9.000 Einwohnern eine Stadt mit besonderem deutsch-georgischen Erbe in der südostgeorgischen Region Niederkartlien, etwa 70 Kilometer südwestlich von Tiflis am Fluss Bolnisistsqali gelegen. Sie wurde 1818 von schwäbischen Pietisten als Kolonie Katharinenfeld gegründet, einer von zahlreichen deutschen Siedlungen, die der russische Zar Alexander I. im Südkaukasus zur Stabilisierung der Region zuließ. Die deutschen Bewohner – vor allem aus Württemberg – brachten Weinbau, Maschinenbau und protestantische Schulorganisation in das überwiegend georgische und armenische Umland. Als 1941 die Sowjetunion mit Hitlerdeutschland in den Krieg trat, deportierte Stalin die deutsche Gemeinschaft komplett nach Kasachstan und Sibirien; die Stadt wurde in Bolnisi umbenannt. Heute erinnern die langgestreckte Hauptstraße mit ihren Walmdachhäusern, die ehemalige evangelische Kirche, das Museum der deutschen Kolonisten und die nahe gelegene altgeorgische Sioni-Basilika aus dem Jahr 478 – eine der ältesten Steinkirchen Georgiens mit der ältesten bekannten georgischen Inschrift – an die jahrhundertelange multikulturelle Geschichte.",
      hu: "Bolniszi mintegy 9000 lakossal különleges német–grúz örökségű város Délkelet-Grúziában, Alsó-Kartli régióban, Tbiliszitől körülbelül 70 kilométerre délnyugatra, a Bolniszisckali folyó partján. Sváb pietisták alapították 1818-ban Katharinenfeld néven, az I. Sándor cár által a déli Kaukázusban a térség stabilizálására engedélyezett német kolóniák egyikeként. A jellemzően württembergi telepesek szőlőtermesztést, gép- és szerszámkészítést, valamint protestáns iskolaszervezetet hoztak a túlnyomórészt grúz és örmény környezetbe. Amikor 1941-ben a Szovjetunió hadba lépett a hitleri Németország ellen, Sztálin a teljes német közösséget Kazahsztánba és Szibériába deportáltatta; a város nevét Bolniszira változtatták. Ma a hosszan elnyúló főutca a kontyolt tetejű házakkal, az egykori evangélikus templom, a német kolonisták helyi múzeuma és a közelben fekvő, 478-ban épült óhgrúz Sioni-bazilika – Grúzia egyik legrégibb kőtemploma, amely a legrégebbi ismert grúz feliratot is őrzi – emlékeztet a város évszázados multikulturális történelmére.",
      ro: "Bolnisi, cu aproximativ 9.000 de locuitori, este un oraș cu o moștenire germano-georgiană aparte, situat în regiunea Kvemo Kartli din sud-estul Georgiei, la circa 70 de kilometri sud-vest de Tbilisi, pe râul Bolnisistsqali. A fost întemeiat în 1818 de coloniști șvabi pietiști, sub numele Katharinenfeld, ca una dintre coloniile germane permise de țarul Alexandru I în sudul Caucazului pentru a stabiliza regiunea. Coloniștii, în mare parte din Württemberg, au adus viticultura, mecanica fină și școala protestantă în zona predominant georgiană și armeană. Când, în 1941, Uniunea Sovietică a intrat în război cu Germania nazistă, Stalin a deportat întreaga comunitate germană în Kazahstan și Siberia, iar orașul a fost redenumit Bolnisi. Astăzi, strada principală alungită, cu casele cu acoperiș în patru ape, fosta biserică evanghelică, muzeul coloniștilor germani și basilica georgiană veche Sioni, ridicată în anul 478 – una dintre cele mai vechi biserici de piatră din Georgia și care păstrează cea mai veche inscripție georgiană cunoscută – evocă istoria multiculturală milenară a orașului.",
      en: "Bolnisi, with around 9,000 inhabitants, is a town with a remarkable German-Georgian heritage in the Kvemo Kartli region of south-eastern Georgia, some 70 kilometres south-west of Tbilisi on the Bolnisistsqali River. It was founded in 1818 by Swabian Pietist settlers under the name Katharinenfeld, one of several German colonies that Tsar Alexander I allowed in the South Caucasus to help stabilise the region. The settlers, mainly from Württemberg, introduced viticulture, mechanical engineering and Protestant schooling into a predominantly Georgian and Armenian environment. When the Soviet Union entered the war against Nazi Germany in 1941, Stalin deported the entire German community to Kazakhstan and Siberia, and the town was renamed Bolnisi. Today the long main street lined with hipped-roof houses, the former Lutheran church, the museum of the German colonists and the nearby Old Georgian Sioni Basilica from the year 478 – one of Georgia's oldest stone churches and home to the earliest known Georgian inscription – recall the town's centuries-long multicultural history.",
image: "/poi-images/ge-bolnisi-cities-v2.webp",
      es: "Bolnisi, con unos 9.000 habitantes, posee una herencia germano-georgiana única. Fue fundada en 1818 por pietistas suabos como la colonia de Katharinenfeld, bajo el permiso del zar Alejandro I. Los colonos trajeron consigo la viticultura avanzada y la organización escolar protestante a la región de Kvemo Kartli. Tras la invasión alemana de la URSS en 1941, Stalin deportó a toda la comunidad a Siberia y Kazajistán, renombrando la ciudad como Bolnisi. Hoy, las casas con techos de media grupa en la calle principal y el museo local mantienen vivo este recuerdo. Además, la cercana basílica de Sioni del año 478 es una de las iglesias de piedra más antiguas del país y contiene las inscripciones en georgiano más antiguas que se conocen.",
      pt: "Bolnisi, com cerca de 9.000 habitantes, possui uma herança luso-alemã especial na região de Kvemo Kartli. Foi fundada em 1818 por pietistas suábios como a colónia de Katharinenfeld, um dos muitos assentamentos alemães permitidos pelo czar Alexandre I. Os habitantes trouxeram a viticultura e a organização escolar para a região. Em 1941, Estaline deportou toda a comunidade alemã para a Sibéria; a cidade foi então renomeada Bolnisi. Hoje, a rua principal com casas de telhado de quatro águas, o museu dos colonos e a antiga Basílica Sioni de 478 — uma das igrejas de pedra mais antigas da Geórgia com as inscrições georgianas mais antigas conhecidas — testemunham esta história multicultural.",
      fr: "Bolnisi, avec environ 9 000 habitants, possède un héritage germano-géorgien unique dans la région de Basse Kartlie. Fondée en 1818 par des piétistes souabes sous le nom de Katharinenfeld, elle fut l'une des nombreuses colonies allemandes autorisées par le tsar Alexandre Ier. Les colons apportèrent la viticulture et l'organisation scolaire dans la région. En 1941, Staline déporta toute la communauté allemande vers la Sibérie et la ville fut renommée Bolnisi. Aujourd'hui, les maisons à toit en croupe de la rue principale, le musée des colons et la basilique de Sioni de 478 — l'une des plus anciennes églises en pierre du pays avec les plus vieilles inscriptions géorgiennes connues — rappellent cette histoire multiculturelle.",
},
