      pt: ["A fortaleza de Akhalkalaki data do século XI.", "A região é conhecida pelas suas batatas excelentes."],
      fr: ["La forteresse d'Akhalkalaki date du XIe siècle.", "La région est célèbre pour ses excellentes pommes de terre."],
